//! Oracle-derived test vectors for the ported tapi32 logic.
//!
//! Vectors come from compiling the verbatim Wine C bodies of the ported functions in
//! `dlls/tapi32/` and `__wine_spec_unimplemented_stub` (`dlls/ntdll/exception.c`) with
//! `gcc -fsanitize=address,undefined -g` under `target/canon/tapi32/`, and running the harness.
//! The harness printed 207 rows. 0 rows were excluded because a sanitizer flagged their scenario.
//! This file is generated by `target/canon/tapi32/gen.py`; do not edit it by hand.

use super::*;

/// What the country-list harness prints: the return value and, when it is 0, the FNV-1a hash of
/// the `total` bytes and the five DWORDs after `dwTotalSize`.
struct CountryRow {
    ret: u32,
    hash: u64,
    header: [u32; 5],
}

/// Runs `line_get_country` on a buffer of `total` bytes (at least 24) filled with 0xAA.
fn run_country(total: u32, id: u32, keys: &[CountryKey]) -> (u32, Vec<u8>) {
    let mut buf = vec![0xaa; (total as usize).max(24)];
    buf[..4].copy_from_slice(&total.to_le_bytes());
    let ret = line_get_country(&mut buf, id, Some(keys));
    (ret, buf)
}

fn fnv1a(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xcbf2_9ce4_8422_2325, |h, &b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)
    })
}

fn check_country(total: u32, id: u32, keys: &[CountryKey], want: CountryRow) {
    let (ret, buf) = run_country(total, id, keys);
    assert_eq!(ret, want.ret);
    if ret == 0 {
        assert_eq!(fnv1a(&buf[..total as usize]), want.hash);
        let header: [u32; 5] = std::array::from_fn(|i| {
            u32::from_le_bytes(buf[4 + 4 * i..8 + 4 * i].try_into().unwrap())
        });
        assert_eq!(header, want.header);
    }
}

fn wide(s: &str) -> Vec<u16> {
    s.encode_utf16().collect()
}

