#[test]
fn oracle_fixed_out_line_negotiate_api_version() {
    let mut out = 0;
    assert_eq!(
        export_kind("lineNegotiateAPIVersion"),
        Some(ExportKind::FixedOut(0))
    );
    assert_eq!(line_negotiate_api_version(0x13, &mut out), 0);
    assert_eq!(out, 19);
}

