#[test]
fn oracle_country_01() {
    // lineGetCountryW, total 512, id 0
    let keys = [
        CountryKey {
            name: "1",
            rules: Some(CountryRules {
                country_code: 1,
                international_rule: b"+1\x00".to_vec(),
                long_distance_rule: b"1\x00".to_vec(),
                country_name: b"United States\x00".to_vec(),
                same_area_rule: b"\x00".to_vec(),
            }),
        },
        CountryKey {
            name: "44",
            rules: Some(CountryRules {
                country_code: 44,
                international_rule: b"+44\x00".to_vec(),
                long_distance_rule: b"0\x00".to_vec(),
                country_name: b"United Kingdom\x00".to_vec(),
                same_area_rule: b"0\x00".to_vec(),
            }),
        },
        CountryKey {
            name: "33",
            rules: Some(CountryRules {
                country_code: 33,
                international_rule: b"+33\x00".to_vec(),
                long_distance_rule: b"0\x00".to_vec(),
                country_name: b"France\x00".to_vec(),
                same_area_rule: b"".to_vec(),
            }),
        },
    ];
    check_country(
        512,
        0,
        &keys,
        CountryRow {
            ret: 0,
            hash: 0xb4216fcd2e10a8ea,
            header: [212, 212, 3, 132, 24],
        },
    );
}

